IF OBJECT\_ID('tempdb..#tmp\_table') IS NOT NULL
 BEGIN
 DROP TABLE #tmp\_table;
 END;

SELECT ROW\_NUMBER() OVER ( ORDER BY a.TBNAME ) AS tms , tbname , tbdesc , b.RowCounts
INTO #tmp\_table
FROM tblist a
JOIN dbo.tablespace b ON a.TBNAME = b.TableName
WHERE ( a.moduleid \<\> '007nfmq38ycx30dv'
 AND a.moduleid IN ( SELECT moduleid
 FROM moduledoc
 WHERE developerid = 'E061W25SK3M' )
 )
 AND a.attr = 'Y'
 AND objecttype = 'T'
 AND a.tbname IN ( SELECT tbname
 FROM tbstru
 WHERE fdname = 'EntId' ) -- and upper(a.tbname) not in("\+kepList.toUpperCase()\+") 
 AND b.RowCounts \<\> 0

